 assert.throws(()=>f.handoff(task,{id:'foreign'}),{code:'entity_not_found'});assert.equal(f.items.store.one('SELECT count(*) n FROM work_item_intents').n,0);assert.equal(f.items.list(f.w).items.length,0);
