 const rootAssignment=f.items.store.one('SELECT snapshot_json FROM work_item_assignments WHERE id=?',accepted.boundary.assignmentId);assert.deepEqual(JSON.parse(rootAssignment.snapshot_json),JSON.parse(task.config_snapshot_json));
 const response=await f.call('GET',f.ws+'/work-items/'+item.id,undefined,f.member.cookie);assert.equal(response.statusCode,200);assert.ok(!response.body.includes('Synthetic tracked business work'));assert.ok(!response.body.includes('source_json'));assert.equal((await f.call('GET',f.ws+'/work-items/'+item.id,undefined,f.outside.cookie)).statusCode,403);
