test('work completion requests system acceptance; only original A acceptance safely completes the item',async t=>{
 const f=await fixture(t);await f.enable();const root=await f.rootTask(),accepted=f.handoff(root,f.employees[1]);f.safe(root,accepted);await f.items.tick();await f.tasks.tick();let item=f.items.list(f.w).items[0],task=f.items.store.one('SELECT t.* FROM tasks t JOIN work_item_task_links l ON t.id=l.task_id WHERE l.assignment_id=?',item.currentAssignmentId);
 const complete=(task,operation)=>{const view=f.items.execute(f.row(task.id),'get_current',{}).item;return f.items.execute(f.row(task.id),'finish',{operationId:operation,expectedAssignmentId:view.currentAssignmentId,expectedVersion:view.version,summary:'Necessary result',completionEvidence:'Synthetic criteria satisfied'});};
 const done=complete(task,'submit');assert.equal(f.items.detail(f.w,item.id).item.status,'pending');f.safe(task,done);await f.items.tick();item=f.items.detail(f.w,item.id).item;assert.equal(item.status,'awaiting_acceptance');assert.equal(item.ownerEmployeeId,f.employees[0].id);assert.equal(item.assignmentKind,'acceptance');
 const reviewer=f.items.store.one('SELECT t.* FROM tasks t JOIN work_item_task_links l ON t.id=l.task_id WHERE l.assignment_id=?',item.currentAssignmentId);assert.ok(reviewer);assert.equal(task.title,'处理：Synthetic work');assert.equal(reviewer.title,'验收：Synthetic work');assert.match(reviewer.input,/SYSTEM ACCEPTANCE ASSIGNMENT/);assert.equal(reviewer.conversation_id,null);await f.tasks.tick();
 const pass=complete(reviewer,'accept');assert.notEqual(f.items.detail(f.w,item.id).item.status,'completed');f.safe(reviewer,pass);await f.items.tick();assert.equal(f.items.detail(f.w,item.id).item.status,'completed');
 await f.finish(root);await f.finish(task);await f.finish(reviewer);await f.notifications.tick();assert.equal(f.items.store.one('SELECT count(*) n FROM task_completion_notifications WHERE task_id IN(?,?,?)',root.id,task.id,reviewer.id).n,0);assert.equal(new Set(f.items.store.all('SELECT session_id FROM runs').map(r=>r.session_id)).size,3);
});
