test('Task tool snapshot is captured at creation, cannot be backfilled, and survives Beta changes',async t=>{
 const f=await fixture(t),initial=await f.rootTask(0,'created-with-default');
 assert.equal(f.items.toolSnapshot(initial.id).betaRevision,1);assert.equal(f.items.toolSnapshot(initial.id).tools.length,5);
 const current=f.items.configuration.get(f.w),closed=f.items.configuration.save(f.w,f.owner.user.id,{expectedRevision:current.revision,enabled:false}),off=await f.rootTask(0,'created-while-off');
 assert.deepEqual(f.items.toolSnapshot(off.id),{version:1,betaRevision:closed.revision,tools:[]});
 assert.throws(()=>f.items.execute(off,'employees',{}),{code:'work_item_tools_not_granted'});
 await f.enable();
 assert.equal(f.items.toolsEnabled(off.id),false,'Enabling later cannot grant tools to an old Task');
 f.items.taskCreated(off.id,f.w);
 assert.equal(f.items.toolsEnabled(off.id),false,'Idempotent capture never rewrites an existing disabled snapshot');
 const on=await f.rootTask(1,'created-while-on'),snapshot=f.items.toolSnapshot(on.id);
 assert.equal(snapshot.tools.length,5);assert.ok(snapshot.tools.includes('work_item_finish'));assert.ok(!snapshot.tools.includes('work_item_create'));
 const settings=f.items.configuration.get(f.w);f.items.configuration.save(f.w,f.owner.user.id,{expectedRevision:settings.revision,enabled:false});
 assert.equal(f.items.status(f.w).enabled,false);
 assert.deepEqual(f.items.toolSnapshot(on.id),snapshot,'No Run-level or Beta reconciliation can replace the Task snapshot');
 assert.ok(Array.isArray(f.items.execute(on,'employees',{}).items),'A previously granted Task may still call the runtime');
 const later=await f.rootTask(2,'created-after-close');assert.equal(f.items.toolsEnabled(later.id),false);
 f.items.store.run('DELETE FROM work_item_task_tool_snapshots WHERE task_id=?',later.id);
 assert.equal(f.items.toolsEnabled(later.id),false,'Pre-upgrade or missing snapshots fail closed');
 assert.throws(()=>f.items.execute(later,'employees',{}),{code:'work_item_tools_not_granted'});
});


test('employee receiver scope and package inherit/custom intersect; legacy custom restrictions and hidden saves survive',async t=>{
 const f=await fixture(t),[a,b,c]=f.employees,caps=f.items.capabilities;
 assert.deepEqual(caps.getHandoffAccess(f.w,b.id),{version:0,allowAll:true,scope:{mode:'all',allowEmployeeIds:[],denyEmployeeIds:[]}});
 const inherited=caps.save(f.w,b.id,pkg('Inherited package')),custom=caps.save(f.w,b.id,pkg('Custom package',{handoffUsageMode:'custom',handoffUsageScope:{mode:'all',allowEmployeeIds:[],denyEmployeeIds:[a.id]}}));
 assert.equal(caps.resolveForHandoff({workspaceId:f.w,entityId:b.id,sourceEmployeeId:a.id}).packages.length,1);
 const policy=caps.saveHandoffAccess(f.w,b.id,{expectedVersion:0,allowAll:false,scope:{mode:'all',allowEmployeeIds:[],denyEmployeeIds:[a.id]}});assert.equal(policy.version,1);
 assert.throws(()=>caps.resolveForHandoff({workspaceId:f.w,entityId:b.id,sourceEmployeeId:a.id}),{code:'employee_handoff_forbidden'},'Even inherited/all/custom packages cannot bypass employee denial');
 assert.equal(caps.resolveForHandoff({workspaceId:f.w,entityId:b.id,sourceEmployeeId:c.id}).packages.length,2,'Only the immediate source C is evaluated');
 assert.throws(()=>caps.saveHandoffAccess(f.w,b.id,{expectedVersion:0,allowAll:true,scope:policy.scope}),{code:'employee_handoff_version_conflict'});
 assert.throws(()=>caps.saveHandoffAccess(f.w,b.id,{expectedVersion:1,allowAll:false,scope:{mode:'all',allowEmployeeIds:[],denyEmployeeIds:['other-workspace']}}),{code:'invalid_handoff_employee_id'});
 caps.saveHandoffAccess(f.w,b.id,{expectedVersion:1,allowAll:false,scope:{mode:'allowlist',allowEmployeeIds:[],denyEmployeeIds:[]}});assert.throws(()=>caps.resolveForHandoff({workspaceId:f.w,entityId:b.id,sourceEmployeeId:c.id}),{code:'employee_handoff_forbidden'});
 caps.saveHandoffAccess(f.w,b.id,{expectedVersion:2,allowAll:true,scope:policy.scope});assert.equal(caps.resolveForHandoff({workspaceId:f.w,entityId:b.id,sourceEmployeeId:a.id}).packages.length,1,'All switch bypasses the preserved custom employee scope');
 const raw=JSON.parse(f.items.store.one('SELECT config_json FROM capability_packages WHERE id=?',custom.id).config_json);delete raw.handoffUsageMode;f.items.store.run('UPDATE capability_packages SET config_json=? WHERE id=?',JSON.stringify(raw),custom.id);assert.equal(caps.list(f.w,b.id).find(p=>p.id===custom.id).handoffUsageMode,'custom');
 const saved=caps.save(f.w,b.id,{...pkg('Old hidden client save'),expectedVersion:custom.version},custom.id);assert.equal(saved.handoffUsageMode,'custom');assert.deepEqual(saved.handoffUsageScope,custom.handoffUsageScope);
 const explicit=caps.save(f.w,b.id,{...pkg('Switch to inherit'),handoffUsageMode:'inherit',expectedVersion:saved.version},custom.id);assert.equal(caps.resolveForHandoff({workspaceId:f.w,entityId:b.id,sourceEmployeeId:a.id}).packages.length,2);assert.deepEqual(explicit.handoffUsageScope,custom.handoffUsageScope,'Switching mode preserves stored custom policy');
 const base=f.ws+'/entities/'+b.id;assert.equal((await f.call('GET',base+'/handoff-access',undefined,f.member.cookie)).statusCode,200);assert.equal((await f.call('GET',base+'/handoff-access',undefined,f.outside.cookie)).statusCode,403);
 await f.enable();const task=await f.rootTask();const before=f.items.execute(task,'employees',{}).items.find(e=>e.id===b.id);assert.equal(before.canReceive,true);caps.saveHandoffAccess(f.w,b.id,{expectedVersion:3,allowAll:false,scope:policy.scope});const after=f.items.execute(task,'employees',{}).items.find(e=>e.id===b.id);assert.equal(after,undefined);assert.throws(()=>f.handoff(task,b),{code:'employee_handoff_forbidden'});assert.equal(f.items.store.one('SELECT count(*) n FROM work_item_intents').n,0);
});

