function assignedTask(f,item){return f.items.store.one('SELECT t.* FROM tasks t JOIN work_item_task_links l ON l.task_id=t.id WHERE l.assignment_id=?',item.currentAssignmentId);}
function completion(f,task,operation='complete'){const item=f.items.execute(f.row(task.id),'get_current',{}).item;return f.items.execute(f.row(task.id),'finish',{operationId:operation,expectedAssignmentId:item.currentAssignmentId,expectedVersion:item.version,summary:'Submitted business result',completionEvidence:'Verified synthetic evidence'});}
async function submitWork(f,task,operation='submit'){const intent=completion(f,task,operation);f.safe(task,intent);await f.items.tick();return f.items.list(f.w).items[0];}
