test('human waiting distinguishes early reply, safe checkpoint and real continuation; late old Run cannot reopen it',async t=>{
 const f=await fixture(t);await f.enable();const root=await f.rootTask(),handoff=f.handoff(root,f.employees[1]);f.safe(root,handoff);await f.items.tick();await f.tasks.tick();let item=f.items.list(f.w).items[0],task=assignedTask(f,item),run=f.items.store.one('SELECT * FROM runs WHERE id=?',task.run_id),sequence=run.sequence;
 const question={questionScope:'synthetic',background:'Local fixture',goal:'Check human wait',knownFacts:[],questions:[{id:'answer',text:'Approve synthetic work?',required:true,answerType:'text'}],completionCriteria:['A definite answer'],proposedAction:'Continue synthetic work',impactScope:'Local fixture only',ifNotConfirmed:'wait'};
 const checkpoint={requestId:randomUUID(),contentVersion:1,question,questionDigest:createHash('sha256').update(JSON.stringify(question)).digest('hex'),taskId:task.id,runId:run.id,sessionId:run.session_id,configurationId:'synthetic',inputRevision:task.input_revision,safe:false};
 f.tasks.ingest(run.id,{eventId:'human-request',runId:run.id,sequence:++sequence,type:'human_request',human:checkpoint});await f.items.tick();item=f.items.list(f.w).items[0];assert.equal(item.status,'waiting');assert.match(item.waitReason,/安全收尾/);
 // Controlled isolated state fixture: this is not a fabricated real person's approval.
 f.items.store.run("UPDATE human_requests SET status='confirmed' WHERE request_id=?",checkpoint.requestId);await f.items.tick();assert.match(f.items.list(f.w).items[0].waitReason,/安全收尾/);assert.equal(f.items.store.one('SELECT count(*) n FROM runs WHERE task_id=?',task.id).n,1);
 f.tasks.ingest(run.id,{eventId:'human-safe',runId:run.id,sequence:++sequence,type:'human_safe',human:{...checkpoint,safe:true,checkpointRef:'b'.repeat(64)}});await f.items.tick();assert.equal(f.row(task.id).status,'waiting_human');assert.match(f.items.list(f.w).items[0].waitReason,/等待可恢复执行/);
 // Simulate the trusted continuation transaction, never the human decision parser.
 const next='synthetic-next-run';f.items.store.run("INSERT INTO runs(id,task_id,session_id,status,sequence,created_at,attempt,kind,parent_run_id) VALUES(?,?,?,'queued',0,?,2,'human_continue',?)",next,task.id,run.session_id,Date.now(),run.id);f.items.store.run("UPDATE tasks SET run_id=?,status='queued' WHERE id=?",next,task.id);f.items.store.run("UPDATE human_requests SET status='continued',continuation_run_id=? WHERE request_id=?",next,checkpoint.requestId);await f.items.tick();assert.equal(f.items.list(f.w).items[0].status,'pending');
 f.items.onEvent(f.row(task.id),{type:'status',runId:run.id,status:'running'});assert.equal(f.items.list(f.w).items[0].status,'pending');f.items.store.run("UPDATE tasks SET status='running' WHERE id=?",task.id);f.items.onEvent(f.row(task.id),{type:'status',runId:next,status:'running'});await f.items.tick();assert.equal(f.items.list(f.w).items[0].status,'in_progress');
});
