test('only a current assignment current Run explicit failure terminates item and emits one source failure notice',async t=>{const f=await fixture(t);await f.enable();const root=await f.rootTask(),h=f.handoff(root,f.employees[1]);f.safe(root,h);await f.items.tick();await f.tasks.tick();const view=f.items.execute(f.row(root.id),'get_current',{}).item,current=f.items.store.one('SELECT t.* FROM tasks t JOIN work_item_task_links l ON l.task_id=t.id WHERE l.assignment_id=?',view.currentAssignmentId);assert.ok(current);assert.equal(current.title,'处理：'+view.title);const seq=f.items.store.one('SELECT sequence FROM runs WHERE id=?',current.run_id).sequence;f.tasks.ingest(current.run_id,{eventId:'explicit-current-failure',runId:current.run_id,sequence:seq+1,type:'status',status:'failed'});await f.items.tick();await f.items.tick();const end=f.items.execute(f.row(root.id),'get_current',{}).item;assert.equal(end.status,'failed');assert.equal(f.items.store.one("SELECT count(*) n FROM work_item_events WHERE kind='failed'").n,1);assert.equal(f.items.store.one('SELECT count(*) n FROM work_item_assignments a JOIN work_item_assignment_roles r ON r.assignment_id=a.id WHERE r.kind=?','acceptance').n,0);await f.notifications.tick();assert.equal(f.items.store.one("SELECT count(*) n FROM work_item_notifications WHERE milestone='failed'").n,1);const before=f.items.store.one('SELECT count(*) n FROM tasks').n;await f.items.tick();assert.equal(f.items.store.one('SELECT count(*) n FROM tasks').n,before);});
test('old source failure and current unknown/waiting never terminate a newer item assignment',async t=>{const f=await fixture(t);await f.enable();const root=await f.rootTask(),h=f.handoff(root,f.employees[1]);f.safe(root,h);await f.items.tick();await f.tasks.tick();const item=f.items.execute(f.row(root.id),'get_current',{}).item,current=f.items.store.one('SELECT t.* FROM tasks t JOIN work_item_task_links l ON l.task_id=t.id WHERE l.assignment_id=?',item.currentAssignmentId);f.items.store.run("UPDATE tasks SET status='failed' WHERE id=?",root.id);f.items.store.run("UPDATE runs SET status='failed' WHERE id=?",root.run_id);for(const state of ['unknown','waiting_human']){f.items.store.run('UPDATE tasks SET status=? WHERE id=?',state,current.id);f.items.store.run('UPDATE runs SET status=? WHERE id=?',state==='waiting_human'?'needs_human':state,current.run_id);await f.items.tick();assert.notEqual(f.items.execute(f.row(root.id),'get_current',{}).item.status,'failed');}assert.equal(f.items.store.one("SELECT count(*) n FROM work_item_events WHERE kind='failed'").n,0);});

test('platform retry API exposes blocked ordinary questions only to manager, enforces role and stale version',async t=>{const f=await fixture(t),root=await f.rootTask();const q={questionScope:'qa',background:'Isolated retry test',goal:'Confirm synthetic local record',knownFacts:[],questions:[{id:'answer',text:'Approve synthetic action?',required:true,answerType:'text'}],completionCriteria:['Explicit decision'],proposedAction:'Local fixture only',impactScope:'Synthetic test',ifNotConfirmed:'wait'};const requestId=randomUUID(),h={requestId,taskId:root.id,runId:root.run_id,sessionId:f.items.store.one('SELECT session_id FROM runs WHERE id=?',root.run_id).session_id,inputRevision:1,contentVersion:1,question:q,questionDigest:createHash('sha256').update(JSON.stringify(q)).digest('hex'),configurationId:'fixed',safe:false};f.items.store.run('INSERT INTO employee_human_rules VALUES(?,?,?,?)',f.w,root.entity_id,1,JSON.stringify([{questionScope:'*',target:{kind:'web',userId:f.member.user.id}}]));f.human.onEvent(root,{eventId:'retry-fixture-request',runId:root.run_id,sequence:1,type:'human_request',human:h});await f.human.tick();const url=f.ws+'/work-items/pending-human',r=await f.call('GET',url,undefined,f.owner.cookie);assert.equal(r.statusCode,200,r.body);const row=r.json().items.find(r=>r.requestId===requestId);assert.equal(row.notificationStatus,'blocked');assert.equal(row.canRetryNotification,true);assert.equal((await f.call('GET',url,undefined,f.member.cookie)).json().items.some(r=>r.requestId===requestId),false);const body={expectedUpdatedAt:row.updatedAt,expectedNotificationStatus:row.notificationStatus};assert.equal((await f.call('POST',url+'/'+requestId+'/retry',body,f.member.cookie)).statusCode,403);assert.equal((await f.call('POST',url+'/'+requestId+'/retry',body,f.owner.cookie)).statusCode,200);assert.equal((await f.call('POST',url+'/'+requestId+'/retry',body,f.owner.cookie)).statusCode,409);f.items.store.run('UPDATE employee_human_rules SET rules_json=? WHERE entity_id=?',JSON.stringify([{questionScope:'*',target:{kind:'web',userId:f.owner.user.id}}]),root.entity_id);await f.human.tick();assert.equal(f.items.store.one('SELECT notification_status FROM human_requests WHERE request_id=?',requestId).notification_status,'delivered');assert.equal(f.items.store.one('SELECT count(*) n FROM runs WHERE task_id=?',root.id).n,1);});

test('same Task older failed Run cannot terminate its current continuing Run; both current statuses must be failed',async t=>{const f=await fixture(t);await f.enable();const root=await f.rootTask(),h=f.handoff(root,f.employees[1]);f.safe(root,h);await f.items.tick();await f.tasks.tick();const item=f.items.execute(f.row(root.id),'get_current',{}).item,current=f.items.store.one('SELECT t.* FROM tasks t JOIN work_item_task_links l ON l.task_id=t.id WHERE l.assignment_id=?',item.currentAssignmentId),previous=f.items.store.one('SELECT * FROM runs WHERE id=?',current.run_id),newId=randomUUID();const next={...previous,id:newId,attempt:previous.attempt+1,status:'running',kind:'human_continue',parent_run_id:previous.id,sequence:0};const columns=Object.keys(next);f.items.store.run('INSERT INTO runs('+columns.join(',')+') VALUES('+columns.map(()=>'?').join(',')+')',...columns.map(k=>next[k]));f.items.store.run("UPDATE runs SET status='failed' WHERE id=?",previous.id);f.items.store.run("UPDATE tasks SET run_id=?,status='running' WHERE id=?",newId,current.id);await f.items.tick();assert.notEqual(f.items.execute(f.row(root.id),'get_current',{}).item.status,'failed');f.items.store.run("UPDATE tasks SET status='failed' WHERE id=?",current.id);await f.items.tick();assert.notEqual(f.items.execute(f.row(root.id),'get_current',{}).item.status,'failed');f.items.store.run("UPDATE runs SET status='failed' WHERE id=?",newId);await f.items.tick();assert.equal(f.items.execute(f.row(root.id),'get_current',{}).item.status,'failed');assert.equal(f.items.store.one("SELECT count(*) n FROM work_item_events WHERE kind='failed'").n,1);});


test('role-only lookup uses the trusted Task assignment, preserves frozen snapshots, and does not read item history',async t=>{
 const f=await fixture(t);await f.enable();const root=await f.rootTask(),frozen=f.items.toolSnapshot(root.id);
 assert.deepEqual(f.items.execute(root,'get_current',{roleOnly:true}),{taskRole:'ordinary'});
 assert.throws(()=>f.items.execute(root,'get_current',{roleOnly:true,after:0}),{code:'invalid_work_item_query'});assert.throws(()=>f.items.execute(root,'get_current',{roleOnly:false}),{code:'invalid_work_item_query'});
 for(const operation of['progress','finish'])assert.throws(()=>f.items.execute(root,operation,{operationId:'unlinked-'+operation,expectedAssignmentId:'invented',expectedVersion:1,...(operation==='finish'?{summary:'result',completionEvidence:'done'}:{})}),{code:'work_item_not_linked'});
 assert.equal(f.items.list(f.w).items.length,0);
 const h=f.handoff(root,f.employees[1]);f.safe(root,h);await f.items.tick();await f.tasks.tick();let view=f.items.list(f.w).items[0],work=assignedTask(f,view);
 assert.deepEqual(f.items.execute(work,'get_current',{roleOnly:true}),{taskRole:'work'});
 assert.throws(()=>f.items.execute(work,'finish',{operationId:'forged',expectedAssignmentId:view.currentAssignmentId,expectedVersion:view.version,summary:'result',completionEvidence:'done',role:'acceptance'}),{code:'invalid_input'});
 const done=f.items.execute(work,'finish',{operationId:'role-complete',expectedAssignmentId:view.currentAssignmentId,expectedVersion:view.version,summary:'result',completionEvidence:'done'});f.safe(work,done);await f.items.tick();await f.tasks.tick();view=f.items.list(f.w).items[0];const reviewer=assignedTask(f,view);
 assert.equal(view.assignmentKind,'acceptance');assert.deepEqual(f.items.execute(reviewer,'get_current',{roleOnly:true}),{taskRole:'acceptance'});assert.deepEqual(f.items.execute(root,'get_current',{roleOnly:true}),{taskRole:'work'},'The root Task must not inherit its later acceptance Task role');assert.deepEqual(f.items.execute(work,'get_current',{roleOnly:true}),{taskRole:'work'});
 assert.deepEqual(f.items.toolSnapshot(root.id),frozen,'Legacy five-tool ceilings are not rewritten');
 const original=f.items.detail;f.items.detail=()=>{throw Error('Item event history must not be read by role-only lookup');};try{assert.deepEqual(f.items.execute(reviewer,'get_current',{roleOnly:true}),{taskRole:'acceptance'});}finally{f.items.detail=original;}
 f.items.store.run("UPDATE work_item_assignment_roles SET kind='forged' WHERE assignment_id=?",view.currentAssignmentId);assert.throws(()=>f.items.execute(reviewer,'get_current',{roleOnly:true}),{code:'work_item_assignment_role_invalid'});
 f.items.store.run('DELETE FROM work_item_assignment_roles WHERE assignment_id=?',view.currentAssignmentId);assert.deepEqual(f.items.execute(reviewer,'get_current',{roleOnly:true}),{taskRole:'work'},'Missing historical role retains the established work default');
 f.items.store.run('DELETE FROM work_item_task_tool_snapshots WHERE task_id=?',reviewer.id);assert.throws(()=>f.items.execute(reviewer,'get_current',{roleOnly:true}),{code:'work_item_tools_not_granted'});
});
